// Accurate GST calculation helper
export function calculateGST(amount: number, rate: number, inclusive: boolean) {
  if (inclusive) {
    const base = amount / (1 + rate / 100);
    return { basePrice: base, gstAmount: amount - base, total: amount };
  }
  const gst = (amount * rate) / 100;
  return { basePrice: amount, gstAmount: gst, total: amount + gst };
}
